# シミュレーション ー ゲームを{動|うご}かそう

:::sensei
{冒険者|ぼうけんしゃ}よ、いよいよゲームの{仕組|しく}みそのものを作るときが{来|き}たよ。
{今日|きょう}はバトルシミュレーションを{作|つく}るんだ！
:::

:::student
バトルシミュレーション！？RPGの{戦闘|せんとう}を{自分|じぶん}で{作|つく}れるの！？
:::

:::sensei
そうだよ！でもひとつ{問題|もんだい}がある。
`Math.random()` は{毎回違|まいかいちが}う{値|あたい}を{返|かえ}すから、{結果|けっか}が{予測|よそく}できないんだ。
テストやチャレンジでは{同|おな}じ{結果|けっか}が{必要|ひつよう}だから、
「シード{付|つ}き{乱数|らんすう}」という{技|わざ}を使うよ。
:::

## シード{付|つ}き{乱数|らんすう}

{同|おな}じシード（{種|たね}）を{与|あた}えれば、{毎回同|まいかいおな}じ{順番|じゅんばん}で{数|かず}が{出|で}る{乱数|らんすう}を作れるよ。

```javascript runnable
function seededRandom(seed) {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed;
}

// 同じシードなら同じ結果
let seed = 42;
for (let i = 0; i < 5; i++) {
  seed = seededRandom(seed);
  console.log("乱数" + (i + 1) + ": " + seed);
}

console.log("---");

// もう一度同じシードで実行 → 同じ結果！
seed = 42;
for (let i = 0; i < 5; i++) {
  seed = seededRandom(seed);
  console.log("再実行" + (i + 1) + ": " + seed);
}
```

:::student
おお！{同|おな}じシードだと{同|おな}じ{数字|すうじ}が{出|で}る！
ゲームのリプレイ{機能|きのう}みたいだね。
:::

## {乱数|らんすう}の{範囲|はんい}を{制御|せいぎょ}する

{大|おお}きな{数値|すうち}を{好|す}きな{範囲|はんい}に{変換|へんかん}する{方法|ほうほう}を{覚|おぼ}えよう。

```javascript runnable
function seededRandom(seed) {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed;
}

let seed = 100;

// 1〜6のサイコロ
console.log("サイコロ:");
for (let i = 0; i < 6; i++) {
  seed = seededRandom(seed);
  let dice = (seed % 6) + 1;
  console.log("  " + dice);
}

// 10〜30のダメージ
console.log("ダメージ:");
for (let i = 0; i < 5; i++) {
  seed = seededRandom(seed);
  let damage = 10 + (seed % 21);  // 10〜30
  console.log("  " + damage);
}
```

:::hint
`seed % N` で `0` から `N-1` の{範囲|はんい}の{数|かず}が{得|え}られるよ。
`min + (seed % (max - min + 1))` で `min` から `max` の{範囲|はんい}にできるんだ。
:::

## ターン{制|せい}バトルの{基本|きほん}

ゲームループの{考|かんが}え{方|かた}を{学|まな}ぼう。`while` ループで{交互|こうご}に{攻撃|こうげき}するよ。

```javascript runnable
function seededRandom(seed) {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed;
}

let seed = 77;
let heroHp = 100;
let monsterHp = 60;
let turn = 1;

console.log("=== バトル開始 ===");
console.log("勇者 HP:" + heroHp + " vs スライム HP:" + monsterHp);

while (heroHp > 0 && monsterHp > 0) {
  console.log("--- ターン" + turn + " ---");

  // 勇者の攻撃
  seed = seededRandom(seed);
  let heroDmg = 10 + (seed % 11);  // 10〜20
  monsterHp -= heroDmg;
  if (monsterHp < 0) monsterHp = 0;
  console.log("勇者の攻撃！ " + heroDmg + "ダメージ（敵HP:" + monsterHp + "）");

  if (monsterHp <= 0) break;

  // モンスターの攻撃
  seed = seededRandom(seed);
  let monDmg = 5 + (seed % 8);  // 5〜12
  heroHp -= monDmg;
  if (heroHp < 0) heroHp = 0;
  console.log("スライムの攻撃！ " + monDmg + "ダメージ（勇者HP:" + heroHp + "）");

  turn++;
}

console.log("=== バトル終了 ===");
if (heroHp > 0) {
  console.log("勇者の勝利！ 残りHP:" + heroHp);
} else {
  console.log("勇者は倒れた...");
}
```

:::sensei
`while (heroHp > 0 && monsterHp > 0)` でどちらかのHPが0になるまでループする。
これがゲームループの{基本|きほん}{形|かたち}だよ！
:::

## {状態管理|じょうたいかんり}をオブジェクトで

{戦闘|せんとう}データをオブジェクトで{管理|かんり}すると、もっと{整理|せいり}されたコードが{書|か}けるよ。

```javascript runnable
function seededRandom(seed) {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed;
}

let seed = 55;

let hero = { name: "ゆうしゃ", hp: 120, maxHp: 120, attack: 25 };
let monster = { name: "ゴブリン", hp: 70, maxHp: 70, attack: 15 };

function doAttack(attacker, defender) {
  seed = seededRandom(seed);
  let variation = seed % 11 - 5;  // -5〜+5
  let dmg = Math.max(1, attacker.attack + variation);
  defender.hp = Math.max(0, defender.hp - dmg);
  console.log(attacker.name + "の攻撃！ " + dmg + "ダメージ！");
  console.log("  " + defender.name + " HP: " + defender.hp + "/" + defender.maxHp);
  return defender.hp <= 0;
}

console.log("=== " + hero.name + " vs " + monster.name + " ===");

let turn = 1;
while (hero.hp > 0 && monster.hp > 0) {
  console.log("[ターン" + turn + "]");

  if (doAttack(hero, monster)) break;
  if (doAttack(monster, hero)) break;

  turn++;
}

let winner = hero.hp > 0 ? hero.name : monster.name;
console.log("勝者: " + winner + "！");
```

:::student
{攻撃処理|こうげきしょり}を{関数|かんすう}にまとめたら、コードがスッキリした！
:::

## クラスを使ったバトルシステム

クラスを使えば、もっと{本格的|ほんかくてき}なバトルシステムが作れるよ。

```javascript runnable
function seededRandom(seed) {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed;
}

let seed = 123;

class Fighter {
  constructor(name, hp, attack, defense) {
    this.name = name;
    this.hp = hp;
    this.maxHp = hp;
    this.attack = attack;
    this.defense = defense;
  }

  isAlive() {
    return this.hp > 0;
  }

  takeDamage(dmg) {
    let actual = Math.max(1, dmg - this.defense);
    this.hp = Math.max(0, this.hp - actual);
    return actual;
  }

  getStatus() {
    return this.name + " HP:" + this.hp + "/" + this.maxHp;
  }
}

let hero = new Fighter("ゆうしゃ", 150, 30, 8);
let boss = new Fighter("ドラゴン", 120, 25, 5);

console.log("=== ボスバトル開始 ===");
let turn = 1;

while (hero.isAlive() && boss.isAlive()) {
  // 勇者の攻撃
  seed = seededRandom(seed);
  let heroRoll = hero.attack + (seed % 11) - 5;
  let dmgToBoss = boss.takeDamage(heroRoll);
  console.log("Turn" + turn + ": " + hero.name + "→" + dmgToBoss + "ダメージ");

  if (!boss.isAlive()) break;

  // ボスの攻撃
  seed = seededRandom(seed);
  let bossRoll = boss.attack + (seed % 11) - 5;
  let dmgToHero = hero.takeDamage(bossRoll);
  console.log("Turn" + turn + ": " + boss.name + "→" + dmgToHero + "ダメージ");

  console.log("  " + hero.getStatus() + " / " + boss.getStatus());
  turn++;
}

console.log("=== バトル終了 ===");
if (hero.isAlive()) {
  console.log(hero.name + "の勝利！ " + hero.getStatus());
} else {
  console.log(boss.name + "の勝利... " + hero.name + "は倒れた");
}
```

:::sensei
`Fighter` クラスに `takeDamage` や `isAlive` メソッドを{持|も}たせることで、
バトルのロジックがとても{分|わ}かりやすくなったね。
{防御力|ぼうぎょりょく}の{計算|けいさん}もクラスの{中|なか}に{閉|と}じ{込|こ}められるのがポイントだよ。
:::

## {複数|ふくすう}の{敵|てき}との{連戦|れんせん}

ループを{二重|にじゅう}にすれば、{連戦|れんせん}シミュレーションも作れるよ。

```javascript runnable
function seededRandom(seed) {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed;
}

let seed = 200;
let heroHp = 200;
let heroAtk = 30;
let wins = 0;

let enemies = [
  { name: "スライム", hp: 30, atk: 8 },
  { name: "ゴブリン", hp: 50, atk: 12 },
  { name: "オーク", hp: 70, atk: 16 },
  { name: "ドラゴン", hp: 100, atk: 22 }
];

console.log("=== 連戦チャレンジ開始！ ===");
console.log("勇者 HP:" + heroHp);

for (let i = 0; i < enemies.length; i++) {
  let enemy = { name: enemies[i].name, hp: enemies[i].hp, atk: enemies[i].atk };
  console.log("--- " + enemy.name + "が現れた！(HP:" + enemy.hp + ") ---");

  while (heroHp > 0 && enemy.hp > 0) {
    seed = seededRandom(seed);
    let heroDmg = heroAtk + (seed % 7);
    enemy.hp -= heroDmg;

    if (enemy.hp <= 0) break;

    seed = seededRandom(seed);
    let enemyDmg = enemy.atk + (seed % 5);
    heroHp -= enemyDmg;
  }

  if (heroHp <= 0) {
    console.log("勇者は" + enemy.name + "に敗れた...");
    break;
  }

  wins++;
  console.log(enemy.name + "を倒した！ 残りHP:" + heroHp);
}

console.log("=== 結果: " + wins + "/" + enemies.length + "体 撃破 ===");
```

## {実践|じっせん}：{完全|かんぜん}バトルログ

{今|いま}までの{全|すべ}てを{組|く}み{合|あ}わせて、{詳細|しょうさい}なバトルログを{出力|しゅつりょく}するシミュレーションを作ろう。

```javascript runnable
function seededRandom(seed) {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed;
}

let seed = 999;
let log = [];

function addLog(msg) {
  log.push(msg);
}

let hero = { name: "ゆうしゃ", hp: 130, maxHp: 130, atk: 28, def: 6 };
let boss = { name: "海竜", hp: 100, maxHp: 100, atk: 22, def: 4 };

addLog("【" + hero.name + " vs " + boss.name + "】");

let turn = 1;
let totalHeroDmg = 0;
let totalBossDmg = 0;

while (hero.hp > 0 && boss.hp > 0) {
  // 勇者の攻撃
  seed = seededRandom(seed);
  let hDmg = Math.max(1, hero.atk + (seed % 9) - 4 - boss.def);
  boss.hp = Math.max(0, boss.hp - hDmg);
  totalHeroDmg += hDmg;
  addLog("T" + turn + ": " + hero.name + "→" + hDmg + "dmg (敵HP:" + boss.hp + ")");

  if (boss.hp <= 0) break;

  // ボスの攻撃
  seed = seededRandom(seed);
  let bDmg = Math.max(1, boss.atk + (seed % 9) - 4 - hero.def);
  hero.hp = Math.max(0, hero.hp - bDmg);
  totalBossDmg += bDmg;
  addLog("T" + turn + ": " + boss.name + "→" + bDmg + "dmg (勇者HP:" + hero.hp + ")");

  turn++;
}

addLog("---");
let winner = hero.hp > 0 ? hero.name : boss.name;
addLog("勝者: " + winner);
addLog("ターン数: " + (turn - 1));
addLog(hero.name + "の総ダメージ: " + totalHeroDmg);
addLog(boss.name + "の総ダメージ: " + totalBossDmg);

// ログを全部表示
for (let i = 0; i < log.length; i++) {
  console.log(log[i]);
}
```

:::sensei
シミュレーションのコツは「{状態|じょうたい}をしっかり{管理|かんり}すること」と
「{結果|けっか}を{記録|きろく}すること」だよ。
シード{付|つ}き{乱数|らんすう}なら{何度|なんど}{実行|じっこう}しても{同|おな}じ{結果|けっか}になるから、
バグを{見|み}つけやすいんだ。
さあ、チャレンジに{挑戦|ちょうせん}してみよう！
:::

## まとめ

- シード{付|つ}き{乱数|らんすう}で{再現可能|さいげんかのう}なランダム{値|あたい}を{生成|せいせい}
- `seed % N` で{範囲|はんい}を{制御|せいぎょ}（`min + seed % (max - min + 1)`）
- `while` ループでゲームループ（{条件|じょうけん}を{満|み}たすまで{繰|く}り{返|かえ}す）
- オブジェクトで{状態|じょうたい}を{管理|かんり}すると{整理|せいり}しやすい
- クラスを使うとキャラクターの{振|ふ}る{舞|ま}いをまとめられる
- ログを{配列|はいれつ}に{記録|きろく}して{後|あと}から{表示|ひょうじ}するテクニック
